// Defer de trabajo costoso fuera del hilo crítico
function procesarLote(items) {
  if (items.length === 0) return;

  // Procesa 1 item ahora
  procesarItem(items[0]);

  // Encola el resto como microtask (alta prioridad pero no bloquea el render)
  if (items.length > 1) {
    queueMicrotask(() => procesarLote(items.slice(1)));
  }
}

function procesarItem(item) {
  // Simulación de trabajo
  console.log('Procesando:', item);
}

procesarLote([1, 2, 3, 4, 5]);
console.log('Esto se ejecuta después del primer item pero antes de los demás');

// Animación con rAF — solo disponible en browser
// (Este ejemplo es conceptual — no ejecutable en el sandbox)

function crearAnimacion(elemento, duracion) {
  let inicio = null;
  let frameId;

  function frame(timestamp) {
    if (!inicio) inicio = timestamp;
    const progreso = Math.min((timestamp - inicio) / duracion, 1);

    // easing: ease-in-out
    const ease = progreso < 0.5
      ? 2 * progreso * progreso
      : 1 - Math.pow(-2 * progreso + 2, 2) / 2;

    elemento.style.opacity = ease;

    if (progreso < 1) {
      frameId = requestAnimationFrame(frame);
    }
  }

  frameId = requestAnimationFrame(frame);
  return () => cancelAnimationFrame(frameId); // Retorna función para cancelar
}

