// Análisis del orden:
// '1' → Síncrono
// setTimeout → MacroQ
// queueMicrotask → MicroQ
// Promise.resolve().then → MicroQ
// '2' → Síncrono
//
// Ejecución:
// Síncronos: '1', '2'
// Microtasks (en orden de encolado): '3', '3b'
// Macrotasks: '4'

const microtaskGanaAMacrotask = true;
const queueMicrotaskEsMicrotask = true;
const orden = ['1', '2', '3', '3b', '4'];

console.log(orden.join(' → '));

class Notificador {
  #pendientes = [];
  #programado = false;
  #handler;

  constructor(handler) {
    this.#handler = handler;
  }

  notificar(mensaje) {
    this.#pendientes.push(mensaje);

    if (!this.#programado) {
      this.#programado = true;
      queueMicrotask(() => {
        const batch = [...this.#pendientes];
        this.#pendientes = [];
        this.#programado = false;
        this.#handler(batch);
      });
    }
  }
}

let llamadas = 0;
const mensajesRecibidos = [];

const n = new Notificador((batch) => {
  llamadas++;
  mensajesRecibidos.push(...batch);
});

// Múltiples notificaciones síncronas → un solo batch
n.notificar('A');
n.notificar('B');
n.notificar('C');

// Espera al siguiente tick
await Promise.resolve();

console.log('Llamadas al handler:', llamadas);
console.log('Mensajes recibidos:', mensajesRecibidos);

function crearAnimador(duracionMs, onFrame) {
  return new Promise(resolve => {
    let progreso = 0;

    function frame() {
      progreso = Math.min(progreso + 16 / duracionMs, 1);
      onFrame(progreso);

      if (progreso < 1) {
        setTimeout(frame, 16); // Simula rAF con ~60fps
      } else {
        resolve(); // Animación completada
      }
    }

    setTimeout(frame, 16); // Primer frame
  });
}

const frames = [];
await crearAnimador(80, (p) => frames.push(Math.round(p * 100)));

console.log('Frames de progreso (%):', frames);
// Debería ser algo como: [20, 40, 60, 80, 100]
